const listAttentionCandidateSessions = `-- name: ListAttentionCandidateSessions :many
SELECT s.id, s.title, s.project_id, s.status,
       CAST(COALESCE(s.status_changed_at, s.created_at) AS TEXT) AS status_since, s.seen_at
FROM sessions s
WHERE s.archived_at IS NULL
  AND s.parent_session_id IS NULL
  AND s.id IN (
    SELECT id FROM sessions WHERE status <> 'idle'
    UNION
    SELECT session_id FROM pending_checkpoint_scopes
    UNION
    SELECT session_id FROM workflow_runs
    WHERE parent_run_id IS NULL AND status IN ('running', 'paused', 'paused_on_child')
    UNION
    SELECT session_id FROM workflow_runs
    WHERE parent_run_id IS NOT NULL AND status IN ('running', 'paused', 'paused_on_child')
    UNION
    SELECT t.session_id FROM turns t
    JOIN sessions ts ON ts.id = t.session_id
    WHERE t.status = 'complete' AND t.completed_at IS NOT NULL
      AND (ts.seen_at IS NULL OR t.completed_at > ts.seen_at)
  )
ORDER BY s.id
`

type ListAttentionCandidateSessionsRow struct {
	ID          string         `json:"id"`
	Title       sql.NullString `json:"title"`
	ProjectID   string         `json:"project_id"`
	Status      string         `json:"status"`
	StatusSince string         `json:"status_since"`
	SeenAt      sql.NullString `json:"seen_at"`
}

// Each union branch uses an index to find active, waiting, or unread sessions.
func (q *Queries) ListAttentionCandidateSessions(ctx context.Context) ([]ListAttentionCandidateSessionsRow, error) {
	rows, err := q.db.QueryContext(ctx, listAttentionCandidateSessions)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListAttentionCandidateSessionsRow
	for rows.Next() {
		var i ListAttentionCandidateSessionsRow
		if err := rows.Scan(
			&i.ID,
			&i.Title,
			&i.ProjectID,
			&i.Status,
			&i.StatusSince,
			&i.SeenAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

