const listSessionTreeIDs = `-- name: ListSessionTreeIDs :many
WITH RECURSIVE tree(id) AS (
    SELECT sessions.id FROM sessions WHERE sessions.id = ?
    UNION
    SELECT s.id FROM sessions s JOIN tree t ON s.parent_session_id = t.id
)
SELECT tree.id FROM tree
`

// Descendant walk for session-tree scoped work. The secret evidence base is
// keyed to a tree, so a sweep must reach every child, not just the root.
func (q *Queries) ListSessionTreeIDs(ctx context.Context, id string) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, listSessionTreeIDs, id)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

