const upsertCompactionView = `-- name: UpsertCompactionView :exec
INSERT INTO compaction_views (session_id, generation, view_json, covered_through_ord, covered_through_message_id, source_seq, tokens_before, tokens_after, created_at)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT(session_id) DO UPDATE SET
    generation = excluded.generation,
    view_json = excluded.view_json,
    covered_through_ord = excluded.covered_through_ord,
    covered_through_message_id = excluded.covered_through_message_id,
    source_seq = excluded.source_seq,
    tokens_before = excluded.tokens_before,
    tokens_after = excluded.tokens_after,
    created_at = excluded.created_at
`

type UpsertCompactionViewParams struct {
	SessionID               string         `json:"session_id"`
	Generation              int64          `json:"generation"`
	ViewJson                string         `json:"view_json"`
	CoveredThroughOrd       int64          `json:"covered_through_ord"`
	CoveredThroughMessageID sql.NullString `json:"covered_through_message_id"`
	SourceSeq               int64          `json:"source_seq"`
	TokensBefore            int64          `json:"tokens_before"`
	TokensAfter             int64          `json:"tokens_after"`
	CreatedAt               string         `json:"created_at"`
}

func (q *Queries) UpsertCompactionView(ctx context.Context, arg UpsertCompactionViewParams) error {
	_, err := q.db.ExecContext(ctx, upsertCompactionView,
		arg.SessionID,
		arg.Generation,
		arg.ViewJson,
		arg.CoveredThroughOrd,
		arg.CoveredThroughMessageID,
		arg.SourceSeq,
		arg.TokensBefore,
		arg.TokensAfter,
		arg.CreatedAt,
	)
	return err
}

