const userIntentBefore = `-- name: UserIntentBefore :one
SELECT m.ts FROM session_source_turns t
JOIN messages m ON m.id = t.opening_message_id
WHERE t.session_id = ? AND m.origin = 'user' AND m.ts <= ?
ORDER BY m.ord DESC LIMIT 1
`

type UserIntentBeforeParams struct {
	SessionID string `json:"session_id"`
	Ts        string `json:"ts"`
}

func (q *Queries) UserIntentBefore(ctx context.Context, arg UserIntentBeforeParams) (string, error) {
	row := q.db.QueryRowContext(ctx, userIntentBefore, arg.SessionID, arg.Ts)
	var ts string
	err := row.Scan(&ts)
	return ts, err
}
